class IndexedProjectionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final BindingSet NO_PARENT = EmptyBindingSet.getInstance();

	@Test
	void projectsAliasesAndPreservesCapturedValuesAcrossReuseOfTheInputRow() {
		var context = context("alias", "source", "unset", "undef", "rejected", "hidden");
		ArrayBindingSet source = context.createBindingSet();
		context.setBinding("undef").accept(null, source);
		Value rejected = VF.createLiteral("rejected");
		Value hidden = VF.createLiteral("hidden");
		source.setBinding("rejected", rejected);
		source.setBinding("hidden", hidden);
		Value first = VF.createLiteral("first");
		Value second = VF.createLiteral("second");
		List<Value> capturedInputs = new ArrayList<>();
		ValueCapturingQueryEvaluationContext capturing = new ValueCapturingQueryEvaluationContext(context, value -> {
			capturedInputs.add(value);
			return value == rejected ? null : VF.createLiteral("captured " + value.stringValue());
		});
		Projection projection = projection(new ProjectionElem("source", "alias"), new ProjectionElem("unset"),
				new ProjectionElem("undef"), new ProjectionElem("rejected"));
		QueryEvaluationContext planning = AdaptiveFilterEvaluationStep.planningContext(projection, capturing);
		var inputs = List.of(first, second).stream().map(value -> {
			source.setBinding("source", value);
			return (BindingSet) source;
		}).iterator();
		try (var rows = new ProjectionIterator(projection, new CloseableIteratorIteration<>(inputs), NO_PARENT,
				planning)) {
			BindingSet firstRow = rows.next();
			BindingSet secondRow = rows.next();
			assertFalse(rows.hasNext());
			assertNotSame(source, firstRow);
			assertNotSame(firstRow, secondRow);
			assertProjectedAlias(firstRow, "captured first");
			assertProjectedAlias(secondRow, "captured second");
		}
		assertEquals(List.of(first, rejected, second, rejected), capturedInputs);
	}

	@Test
	void outerProjectionRetainsParentLookupAndLastBoundAliasPrecedence() {
		var context = context("first", "second", "target", "hidden");
		var source = context.createBindingSet();
		var parent = context.createBindingSet();
		Value earlier = VF.createLiteral("earlier");
		Value later = VF.createLiteral("later parent value");
		source.setBinding("first", earlier);
		parent.setBinding("second", later);
		parent.setBinding("hidden", VF.createLiteral("parent-only value"));
		BindingSet row = project(projection(new ProjectionElem("first", "target"),
				new ProjectionElem("second", "target")), source, parent, context);
		assertEquals(Set.of("target"), row.getBindingNames());
		assertSame(later, row.getValue("target"));

		BindingSet withoutLater = project(projection(new ProjectionElem("first", "target"),
				new ProjectionElem("second", "target")), source, NO_PARENT, context);
		assertSame(earlier, withoutLater.getValue("target"));
	}

	@Test
	void nestedProjectionRetainsUnselectedParentBindings() {
		var context = context("local", "alias", "inherited");
		var source = context.createBindingSet();
		var parent = context.createBindingSet();
		Value local = VF.createLiteral("local");
		Value inherited = VF.createLiteral("inherited");
		source.setBinding("local", local);
		parent.setBinding("inherited", inherited);
		Projection nested = projection(new ProjectionElem("local", "alias"));
		new Projection(nested, new ProjectionElemList(new ProjectionElem("alias")));

		BindingSet row = project(nested, source, parent, context);
		assertEquals(Set.of("alias", "inherited"), row.getBindingNames());
		assertSame(local, row.getValue("alias"));
		assertSame(inherited, row.getValue("inherited"));
	}

	@Test
	void graphFrameAndMapInputsRetainProjectionSemantics() {
		var context = context("graph", "local", "alias");
		var graph = VF.createIRI("urn:graph");
		Value local = VF.createLiteral("local");
		var graphInput = context.createBindingSet();
		GraphFrameBindings.supply(graphInput, "graph", graph);
		graphInput.setBinding("local", local);
		var map = new MapBindingSet();
		map.addBinding("local", local);
		for (BindingSet input : List.of(graphInput, map)) {
			BindingSet row = project(projection(new ProjectionElem("local", "alias")), input, NO_PARENT, context);
			assertEquals(Set.of("alias"), row.getBindingNames());
			assertSame(GraphFrameBindings.EMPTY, GraphFrameBindings.from(row));
			assertSame(local, row.getValue("alias"));
		}
	}

	@Test
	void differentArrayLayoutAndSubclassRetainLegacyReads() {
		var context = context("source", "alias");
		var indexed = context.indexedBindingLayout();
		int[] sources = { indexed.slot("source") };
		int[] targets = { indexed.slot("alias") };
		assertNotNull(indexed.project(context.createBindingSet(), sources, targets));

		var otherLayout = context("source", "alias").createBindingSet();
		Value value = VF.createLiteral("other layout");
		otherLayout.setBinding("source", value);
		assertNull(indexed.project(otherLayout, sources, targets));
		assertSame(value, project(projection(new ProjectionElem("source", "alias")), otherLayout, NO_PARENT,
				context).getValue("alias"));

		var emptyChecks = new AtomicInteger();
		var subclass = new ArrayBindingSet("source", "alias") {
			@Override
			public boolean isEmpty() {
				emptyChecks.incrementAndGet();
				return true;
			}
		};
		subclass.setBinding("source", value);
		assertNull(indexed.project(subclass, sources, targets));
		BindingSet projected = project(projection(new ProjectionElem("source", "alias")), subclass, NO_PARENT, context);
		assertTrue(projected.isEmpty());
		assertEquals(1, emptyChecks.get(), "fallback must call the overridden getter guard");
	}

	@Test
	void projectsWideRowsAndEmptyProjectionWithoutLosingBindingMetadata() {
		String[] names = IntStream.range(0, 65).mapToObj(index -> "v" + index).toArray(String[]::new);
		var context = context(names);
		var input = context.createBindingSet();
		Value first = VF.createLiteral("first");
		Value last = VF.createLiteral("last");
		input.setBinding("v0", first);
		input.setBinding("v64", last);
		BindingSet row = project(projection(new ProjectionElem("v0"), new ProjectionElem("v1"),
				new ProjectionElem("v64")), input, NO_PARENT, context);
		assertEquals(Set.of("v0", "v64"), row.getBindingNames());
		assertEquals(2, row.size());
		assertFalse(row.isEmpty());
		assertSame(first, row.getValue("v0"));
		assertSame(last, row.getValue("v64"));
		BindingSet empty = project(projection(), input, NO_PARENT, context);
		assertTrue(empty.isEmpty());
		assertEquals(0, empty.size());
		assertEquals(Set.of(), empty.getBindingNames());
	}

	@Test
	void emptyProjectionDoesNotInspectANullSourceRow() {
		var inputs = Collections.<BindingSet>singletonList(null).iterator();
		try (var rows = new ProjectionIterator(projection(), new CloseableIteratorIteration<>(inputs), NO_PARENT,
				context("unused"))) {
			assertTrue(rows.next().isEmpty());
			assertFalse(rows.hasNext());
		}
	}

	private static void assertProjectedAlias(BindingSet row, String label) {
		assertEquals(Set.of("alias"), row.getBindingNames());
		assertEquals(1, row.size());
		assertFalse(row.isEmpty());
		assertEquals(VF.createLiteral(label), row.getValue("alias"));
		var expected = new MapBindingSet();
		expected.addBinding("alias", VF.createLiteral(label));
		assertEquals(expected, row);
		assertEquals(expected.hashCode(), row.hashCode());
	}

	private static BindingSet project(Projection projection, BindingSet source, BindingSet parent,
			QueryEvaluationContext context) {
		try (var rows = new ProjectionIterator(projection,
				new CloseableIteratorIteration<>(List.of(source).iterator()), parent, context)) {
			return rows.next();
		}
	}

	private static Projection projection(ProjectionElem... elements) {
		return new Projection(new SingletonSet(), new ProjectionElemList(elements));
	}

	private static ArrayBindingBasedQueryEvaluationContext context(String... names) {
		return new ArrayBindingBasedQueryEvaluationContext(new QueryEvaluationContext.Minimal((Dataset) null), names,
				null);
	}
}
